  'Training and Development',
  'This course prepares undergraduate human resources students to design, deliver, evaluate, and improve employee learning and talent development initiatives. Students examine needs assessment, objectives, instructional design, adult learning, delivery methods, e-learning, coaching, mentoring, leadership development, evaluation models, training module design, learning transfer, performance consulting, skills-based development, AI-enabled learning, and learning analytics.',
  $trdvjson${"slug": "training-and-development", "title": "Training and Development", "description": "This course prepares undergraduate human resources students to design, deliver, evaluate, and improve employee learning and talent development initiatives. Students examine needs assessment, objectives, instructional design, adult learning, delivery methods, e-learning, coaching, mentoring, leadership development, evaluation models, training module design, learning transfer, performance consulting, skills-based development, AI-enabled learning, and learning analytics.", "topics": [{"id": "a3f44ef2-7c22-4f4d-a991-1827dba487e5", "type": "topic", "title": "Needs Assessment", "description": "This section teaches students to begin training with a real performance or capability need, not a preselected workshop. Students learn to diagnose organizational, task, and learner gaps before recommending any learning solution.", "children": [{"id": "66c372d2-b23c-4781-bdd7-8779b0dff7fd", "type": "subtopic", "title": "Organizational analysis", "children": [{"id": "01f1bb0e-4a19-4e02-a4fe-d697a99cd722", "type": "concept", "title": "Business goals and performance gaps"}, {"id": "156d291f-6e10-4b80-a3be-6d1df8f1a068", "type": "concept", "title": "Stakeholder expectations"}, {"id": "4fe2a48b-b971-4a31-b070-d69c699ca9fa", "type": "concept", "title": "Constraints, resources, and readiness"}], "description": "The point is to connect training needs to strategy, performance, risk, and workforce priorities."}, {"id": "31ea6d28-f6af-47e3-b1ee-ec33e3dd335d", "type": "subtopic", "title": "Task and competency analysis", "children": [{"id": "127311f7-b387-45b4-8f82-0fdaa8bb17e8", "type": "concept", "title": "Tasks, duties, and workflows"}, {"id": "24bdb689-629e-47c6-ac63-6880c2f7aaf6", "type": "concept", "title": "Knowledge, skills, abilities, and behaviors"}, {"id": "82d2195e-9178-4549-b41c-20630dd6ffd4", "type": "concept", "title": "Competency models and proficiency levels"}], "description": "Students learn to identify what employees must do and what capabilities are required."}, {"id": "01251df4-0d5c-4f6b-abd6-36f12eba515d", "type": "subtopic", "title": "Learner analysis", "children": [{"id": "dcc2612b-4db8-455a-b2bc-267cda21114b", "type": "concept", "title": "Prior knowledge and experience"}, {"id": "27b96fb3-6caf-4fea-93d4-24b7078db475", "type": "concept", "title": "Motivation and barriers"}, {"id": "10301211-1001-4da6-adb9-54bc5447a7ec", "type": "concept", "title": "Accessibility, language, and technology access"}], "description": "This subtopic helps students design for the actual audience."}, {"id": "0ac9c0ea-bd89-46cc-a02a-255c686695ec", "type": "subtopic", "title": "Data collection methods", "children": [{"id": "15847b91-540a-47d2-a7ce-f7ce92e986ee", "type": "concept", "title": "Interviews, focus groups, surveys, and observation"}, {"id": "00b14baf-d7b8-433f-bb28-f98cd29744e6", "type": "concept", "title": "Performance data and error reports"}, {"id": "c6bc73ad-cb4c-404f-97df-69bc59291c7d", "type": "concept", "title": "Root cause analysis"}], "description": "Students learn to gather evidence rather than rely on assumptions."}]}, {"id": "2fb757f8-4278-4050-8647-0787bc8f9504", "type": "topic", "title": "Learning Objectives", "description": "Learning objectives translate needs into observable outcomes. Students learn to write objectives that guide design, instruction, practice, feedback, and evaluation.", "children": [{"id": "035ef8f3-3c10-42ec-80fc-747a6232fcd6", "type": "subtopic", "title": "Objective structure", "children": [{"id": "63483d39-71f2-4b25-ba51-3d65b9b0b7c2", "type": "concept", "title": "Audience, behavior, condition, and standard"}, {"id": "bcbe7e00-de83-4a25-be51-556fda25770b", "type": "concept", "title": "Action verbs"}, {"id": "383f1b7f-aad9-4bcb-9add-82b945702faa", "type": "concept", "title": "Observable performance"}], "description": "Students learn to write objectives that are clear and measurable."}, {"id": "ebf37716-7f61-426a-923e-57eef5f95694", "type": "subtopic", "title": "Cognitive, skill, and attitude outcomes", "children": [{"id": "9709fd2a-c35e-4802-a239-c055057f653e", "type": "concept", "title": "Knowledge and comprehension"}, {"id": "0a5b0ca2-521a-41d5-8bb3-2a94394835c1", "type": "concept", "title": "Procedural and interpersonal skills"}, {"id": "ea912b26-53be-42ef-b765-2e8b484ac800", "type": "concept", "title": "Mindset, motivation, and confidence"}], "description": "The gist is to match objectives to what learners must know, do, or value."}, {"id": "7de9fbbe-f23c-4a22-9031-6708aebf99a7", "type": "subtopic", "title": "Alignment with assessment", "children": [{"id": "383e34be-ba44-4433-b9bc-c1ba174b7ccb", "type": "concept", "title": "Knowledge checks"}, {"id": "2c48bcc9-d20b-4c0c-886c-ee9ccb00677b", "type": "concept", "title": "Skill demonstrations"}, {"id": "c54e8756-d98f-4232-af98-e6de1440dc77", "type": "concept", "title": "Scenario-based assessment"}], "description": "Students learn that objectives should predict how learning will be checked."}, {"id": "1ba3102b-f4fd-4174-8af0-83817829fb32", "type": "subtopic", "title": "Objective quality review", "children": [{"id": "21ab8d15-3b15-4145-9654-fcbc8008bd7d", "type": "concept", "title": "Avoiding fuzzy verbs"}, {"id": "93b047cb-4e8d-43b3-9735-26adc1845545", "type": "concept", "title": "Setting realistic standards"}, {"id": "1ca71580-fcc2-4389-a0d9-d410001110e1", "type": "concept", "title": "Linking objectives to business outcomes"}], "description": "This subtopic helps students refine vague training goals."}]}, {"id": "36b75a57-62c6-4b69-8b63-42b5d06e26d7", "type": "topic", "title": "Instructional Design", "description": "Instructional design turns objectives into a structured learning experience. Students learn to sequence content, practice, feedback, media, and assessment so learners can transfer new skills to work.", "children": [{"id": "529fd92c-487b-4be9-962d-a4c475e7a25c", "type": "subtopic", "title": "Design models", "children": [{"id": "faa23086-0ae9-4b2f-9ec9-469e75a5eca0", "type": "concept", "title": "ADDIE"}, {"id": "9ccc9764-fab5-42ef-8b19-0e617341e228", "type": "concept", "title": "SAM and agile design"}, {"id": "10e7c079-71bf-43dd-9e6d-84027dbd401f", "type": "concept", "title": "Backward design"}], "description": "Students learn common models for organizing training projects."}, {"id": "d4569708-e525-4921-ab2a-0aaf137b4108", "type": "subtopic", "title": "Content sequencing", "children": [{"id": "db01657a-ea9e-4533-89fc-e0bfd1f83385", "type": "concept", "title": "Chunking and scaffolding"}, {"id": "b6e73a3d-d0ab-4462-b069-6cc9afeb070f", "type": "concept", "title": "Worked examples"}, {"id": "07b743e4-86de-4a07-9d77-6764d068940a", "type": "concept", "title": "Practice progression"}], "description": "The point is to build learning from simple to complex and from knowledge to performance."}, {"id": "39c78b59-e7a5-4890-ab3b-95d13099f459", "type": "subtopic", "title": "Practice and feedback", "children": [{"id": "50e8c28d-a4a2-4338-b054-cee3060ef708", "type": "concept", "title": "Deliberate practice"}, {"id": "2332fccd-86fd-4017-b121-b35bc024dfab", "type": "concept", "title": "Feedback timing and specificity"}, {"id": "974feb15-af00-4f46-8c3f-560a5c2d35e6", "type": "concept", "title": "Reflection and coaching prompts"}], "description": "Students learn that performance improves through retrieval, application, and correction."}, {"id": "923389e8-59d4-4e3b-9b8d-ab5ece970d76", "type": "subtopic", "title": "Inclusive learning design", "children": [{"id": "20f8387c-0807-42b2-ba2c-6e60c7947f17", "type": "concept", "title": "Universal design for learning"}, {"id": "e1e0e8c2-c82c-4f6f-9c58-39a7f53fcbf1", "type": "concept", "title": "Accessibility and plain language"}, {"id": "806f6a47-bdd4-4ec1-bb9f-fad67ffa151d", "type": "concept", "title": "Culturally responsive examples"}], "description": "This subtopic ensures design works for varied learners."}]}, {"id": "b0e5bf3d-54ad-41f3-b040-035f1dbdf1c8", "type": "topic", "title": "Adult Learning Theory", "description": "Adult learning theory helps students design training for experienced learners who bring goals, prior knowledge, constraints, and workplace realities. The focus is practical, respectful, self-directed learning.", "children": [{"id": "98bd1abd-7ad2-4ebd-9e2d-68e5c2482a98", "type": "subtopic", "title": "Andragogy and learner autonomy", "children": [{"id": "6689c4d1-0f9c-43e3-b2e5-9ba8c9594eb2", "type": "concept", "title": "Need to know"}, {"id": "4d9b6d42-4102-479c-b25d-d27dd0358b9b", "type": "concept", "title": "Experience as a resource"}, {"id": "e8da8e4b-e7cb-41eb-835a-ca15673e7e68", "type": "concept", "title": "Problem-centered learning"}], "description": "Students learn why adults need relevance, agency, and respect."}, {"id": "f1950bce-5ac2-4866-abe6-b63baa63296d", "type": "subtopic", "title": "Learning science", "children": [{"id": "1141208b-9b05-4177-9bb1-f1a899489fe6", "type": "concept", "title": "Retrieval practice"}, {"id": "b631481e-ea0b-4c98-99d7-d5c2f1fb43fa", "type": "concept", "title": "Spacing and interleaving"}, {"id": "9d57ff7c-c636-4b47-b8c1-822326d0a51a", "type": "concept", "title": "Cognitive load"}], "description": "The gist is to use evidence about memory, attention, practice, and retention."}, {"id": "af4b50e9-1247-4dfc-b4b4-799e9b836211", "type": "subtopic", "title": "Motivation and engagement", "children": [{"id": "50b28bcc-973d-418c-89bd-994434bc6da0", "type": "concept", "title": "Self-efficacy"}, {"id": "ae93a08a-8ddd-4021-9e95-831c228b8045", "type": "concept", "title": "Relevance and value"}, {"id": "955b291b-51b1-4459-b56e-f87b17545e10", "type": "concept", "title": "Psychological safety"}], "description": "Students learn to design for learner effort and persistence."}, {"id": "3a6c3080-35dd-4b69-912a-ca9ebd824364", "type": "subtopic", "title": "Transfer conditions", "children": [{"id": "d63a7cae-caa7-4177-bf60-29eacf5b58d1", "type": "concept", "title": "Manager support"}, {"id": "43bb7529-1550-426b-8dd8-28d7a4cfe8af", "type": "concept", "title": "Opportunities to practice"}, {"id": "8a2953b2-8bda-4438-93dd-98a8c7095015", "type": "concept", "title": "Cues, tools, and reinforcement"}], "description": "This subtopic links learning theory to workplace behavior."}]}, {"id": "76de87d6-28bb-4da3-b7e9-f4ce646a678c", "type": "topic", "title": "Delivery Methods", "description": "Delivery method choices shape access, engagement, cost, practice quality, and transfer. Students learn to choose delivery formats based on objectives and context rather than novelty.", "children": [{"id": "beb00876-b6dc-4bd7-92e4-02efab4a7388", "type": "subtopic", "title": "Instructor-led training", "children": [{"id": "de3722a4-080a-46ea-9b55-df7e0cc48e85", "type": "concept", "title": "Discussion and practice"}, {"id": "83cbe03c-881b-4f8b-9c8e-e39ce630f65b", "type": "concept", "title": "Role play and simulation"}, {"id": "cb440c70-bae9-4c00-b5c1-fa4323a70523", "type": "concept", "title": "Facilitator skill and group management"}], "description": "Students learn when live facilitation is valuable."}, {"id": "29b57e98-d1cd-45c6-91e0-f2232bd64547", "type": "subtopic", "title": "On-the-job and experiential learning", "children": [{"id": "d313103e-3476-4a05-b56a-e4241e5735d8", "type": "concept", "title": "Job shadowing and stretch assignments"}, {"id": "319c4cf3-4dd1-4aee-94af-d1e5bc89bfdf", "type": "concept", "title": "Apprenticeship and guided practice"}, {"id": "7d3fba67-86bd-4522-9513-772d304728b8", "type": "concept", "title": "After-action reviews"}], "description": "The point is to use real work as a learning environment."}, {"id": "8ca8466e-4282-4015-8057-07dbc622512c", "type": "subtopic", "title": "Blended learning", "children": [{"id": "2fbe9787-722f-4725-88b0-6a440fdad06e", "type": "concept", "title": "Prework and live session design"}, {"id": "38d72741-c540-4c10-8874-d6f7e4428ee8", "type": "concept", "title": "Digital practice and workplace application"}, {"id": "01600cf1-05ee-4766-82d0-a5508d70aad6", "type": "concept", "title": "Learning journeys"}], "description": "Students learn to combine formats deliberately."}, {"id": "8198e966-2d0b-4d6b-ad8f-a8d6ad7603a0", "type": "subtopic", "title": "Method selection criteria", "children": [{"id": "2facd718-6482-4f31-bde2-515ff021b61d", "type": "concept", "title": "Learning objective fit"}, {"id": "47015d8a-732f-4ab4-906b-99ac6658f1f6", "type": "concept", "title": "Audience and scale"}, {"id": "6f10238c-f849-4828-a69d-d01cc69ee8cc", "type": "concept", "title": "Cost, logistics, risk, and accessibility"}], "description": "This subtopic gives students a decision lens."}]}, {"id": "6d281459-ba77-4063-97f9-7089878ea329", "type": "topic", "title": "E-Learning and Learning Technology", "description": "Technology expands training reach but does not guarantee learning. Students learn to design e-learning, LMS experiences, and digital tools that support practice, feedback, and measurable outcomes.", "children": [{"id": "73cfcdfe-6155-4ec9-a46b-05f299890852", "type": "subtopic", "title": "E-learning formats", "children": [{"id": "4d4002a4-b6a7-461f-8547-94077196347b", "type": "concept", "title": "Self-paced modules"}, {"id": "96c70585-0d22-4c30-9cfc-9fe28ccb5214", "type": "concept", "title": "Virtual instructor-led training"}, {"id": "d50cfb0b-de71-4ef2-a45c-4dec94b43a51", "type": "concept", "title": "Microlearning and performance support"}], "description": "Students learn the strengths and limits of common online learning modes."}, {"id": "11f35918-7044-4b56-b468-642bdc7597a7", "type": "subtopic", "title": "Learning management systems", "children": [{"id": "5678e3b9-31bd-4d7d-b294-5b718956df26", "type": "concept", "title": "Enrollment and completion tracking"}, {"id": "a44aaacb-3bdf-4ee5-919f-ec2e4fe73151", "type": "concept", "title": "Assessments and certificates"}, {"id": "9d3d53b5-0856-42b4-9c7e-4030f5d4885d", "type": "concept", "title": "Data and reporting"}], "description": "The gist is to understand how training is assigned, tracked, and reported."}, {"id": "93b35cec-9bb9-4410-9833-1456091b5640", "type": "subtopic", "title": "Digital engagement design", "children": [{"id": "60a4e77b-bcc3-416f-91a7-f5477cd49a24", "type": "concept", "title": "Interactive scenarios"}, {"id": "d8429ae2-efb5-45ed-9949-4b42646fa0fa", "type": "concept", "title": "Branching decisions"}, {"id": "96ba644c-5cf8-4fe8-8e78-aa95dd52495d", "type": "concept", "title": "Knowledge checks and reflection"}], "description": "Students learn to avoid passive click-through learning."}, {"id": "05edc1ee-c4df-4c8b-8536-78ee5ddf94c0", "type": "subtopic", "title": "Technology selection and accessibility", "children": [{"id": "4cefed62-5ad3-4052-ade4-886428dc5760", "type": "concept", "title": "Mobile access"}, {"id": "f9d08745-3ba3-41bc-8d6c-fc206adbc86b", "type": "concept", "title": "WCAG and accessibility"}, {"id": "322c9b16-2432-405e-b7cd-2548b3237a16", "type": "concept", "title": "Data privacy and vendor review"}], "description": "This subtopic connects tools to user needs and constraints."}]}, {"id": "9a3f88e3-aa03-4d75-8575-21f11369aef2", "type": "topic", "title": "Coaching and Mentoring", "description": "Coaching and mentoring support development beyond formal classes. Students learn the difference between these practices and how they build skill, confidence, career growth, and performance.", "children": [{"id": "15a91aaf-4a03-4872-9fa6-c891ebf6cb94", "type": "subtopic", "title": "Coaching fundamentals", "children": [{"id": "c74cf505-fb48-4f03-b707-fab8be51b9c9", "type": "concept", "title": "Goal setting"}, {"id": "16d18e44-a737-465f-a767-731f358ed465", "type": "concept", "title": "Powerful questions"}, {"id": "773d1ee2-2a5e-47be-aeda-e4b515f9ec10", "type": "concept", "title": "Feedback and accountability"}], "description": "Students learn how coaching supports performance improvement and self-directed problem solving."}, {"id": "b3a640e5-9bd5-4910-9336-680c446c8162", "type": "subtopic", "title": "Mentoring relationships", "children": [{"id": "3ffd50a3-6414-40fe-820f-ccefb66cd53a", "type": "concept", "title": "Mentor matching"}, {"id": "83cff25d-0354-4cbc-abd8-f43e6464ee69", "type": "concept", "title": "Expectations and boundaries"}, {"id": "38ec1bd8-b8d0-4b69-87b1-1f2a29a00450", "type": "concept", "title": "Developmental networks"}], "description": "The point is to support longer-term career and professional development."}, {"id": "d955c1e6-faa7-4cb0-94ee-781525fc5ec0", "type": "subtopic", "title": "Manager as coach", "children": [{"id": "82b627b4-8360-4ce7-9a7c-c169130ab622", "type": "concept", "title": "Observation and feedback"}, {"id": "58c7ba8d-2efc-40a2-b0fb-ec8e528e18c9", "type": "concept", "title": "One-on-one development conversations"}, {"id": "7c576086-adb8-4808-a1c8-498a15e6ab8a", "type": "concept", "title": "Psychological safety"}], "description": "Students learn how supervisors reinforce learning in day-to-day work."}, {"id": "f5c79acb-df28-4315-b984-de4a62ee41bf", "type": "subtopic", "title": "Evaluating coaching and mentoring", "children": [{"id": "5b2988ba-0b58-4aa5-89c7-a67ca95cb376", "type": "concept", "title": "Participation and satisfaction"}, {"id": "6f8f88fd-dc15-4d0a-bdb6-ae9db1bb0f11", "type": "concept", "title": "Goal progress"}, {"id": "f0a2c6c3-61d9-4bce-a9b9-ec91b6cb2d9d", "type": "concept", "title": "Retention, mobility, and performance indicators"}], "description": "This subtopic helps students assess whether relationships are producing value."}]}, {"id": "7ad9a114-aeac-43a8-b00c-0de71a6cb5dc", "type": "topic", "title": "Leadership Development", "description": "Leadership development builds the capability of people who influence others and execute strategy. Students learn to design programs that develop behavior, judgment, self-awareness, and organizational impact.", "children": [{"id": "a9def6ca-e6f3-41e9-9ac4-ebe2f1fba7e0", "type": "subtopic", "title": "Leadership competency models", "children": [{"id": "52a94b8e-dc6e-49ea-a8a9-d602628c8b4f", "type": "concept", "title": "Strategic thinking"}, {"id": "7fec9951-8418-4c1b-96b7-cb12d59f3ae4", "type": "concept", "title": "Communication and influence"}, {"id": "20d43ad8-1a33-47be-ba64-90981320c68c", "type": "concept", "title": "Inclusion, ethics, and change leadership"}], "description": "Students learn to define what leadership should look like in a specific organization."}, {"id": "2ca48951-b524-4067-8113-0791994690c9", "type": "subtopic", "title": "Development methods", "children": [{"id": "17b497ca-0c96-4a2e-98a9-5692c3ad47b6", "type": "concept", "title": "Assessments and 360 feedback"}, {"id": "81a8fb2f-e0bc-4e3c-b9c8-5be691fb64ba", "type": "concept", "title": "Action learning and projects"}, {"id": "8c632728-e483-415b-b849-4ef795a6c8e5", "type": "concept", "title": "Coaching, mentoring, and peer learning"}], "description": "The gist is to combine learning experiences rather than rely only on seminars."}, {"id": "7ee815e9-5888-4302-a7c3-c52f7db26694", "type": "subtopic", "title": "Succession and pipeline development", "children": [{"id": "08eec7ae-9089-4cd6-bd19-43055854b3f4", "type": "concept", "title": "High-potential identification"}, {"id": "05988233-1921-42d4-a3af-ede53068bad1", "type": "concept", "title": "Bench strength"}, {"id": "59138bf1-a89d-405e-9102-473f1ef1b310", "type": "concept", "title": "Readiness and transition support"}], "description": "Students learn how leadership development links to talent strategy."}, {"id": "2a4d7588-12c9-4b3a-9f4b-bab22d67e4c1", "type": "subtopic", "title": "Leadership program evaluation", "children": [{"id": "e718e455-7a43-40ec-aaef-14b23f0bdcef", "type": "concept", "title": "Behavior change"}, {"id": "0bdfd708-190e-4d5f-93e9-dbf2b419a4b1", "type": "concept", "title": "Team outcomes"}, {"id": "0b47a0ce-042f-4eda-ad40-2eb0a443e850", "type": "concept", "title": "Business and culture impact"}], "description": "This subtopic asks whether leadership development changes behavior and outcomes."}]}, {"id": "9cd1a9f8-8210-41c2-9300-8990478ba51b", "type": "topic", "title": "Evaluation Models", "description": "Evaluation tells whether training worked, for whom, why, and at what value. Students learn to use evaluation models to improve learning design and communicate impact.", "children": [{"id": "e25f6fa5-b6be-41e3-aa5f-85429633bb7d", "type": "subtopic", "title": "Kirkpatrick model", "children": [{"id": "638c7952-c599-47e9-9bd0-b31d4b822cdf", "type": "concept", "title": "Reaction"}, {"id": "73ba7d52-982e-47f1-82f7-2b5fd1ae6e4e", "type": "concept", "title": "Learning"}, {"id": "ccf543ec-5fc9-4bad-a7f7-5c9a4ccd78e2", "type": "concept", "title": "Behavior"}, {"id": "c3bcd7eb-c176-41d0-ad7c-ef80c2aa02dd", "type": "concept", "title": "Results"}], "description": "Students learn the classic levels of training evaluation."}, {"id": "0f8bc5ee-cc57-4828-9608-d9d446f48eec", "type": "subtopic", "title": "Phillips ROI and impact logic", "children": [{"id": "cf5c35a7-cd80-4e76-bb84-a254dc090476", "type": "concept", "title": "ROI calculations"}, {"id": "0e765ed9-fcae-45fa-bde1-d34f6454f6cd", "type": "concept", "title": "Isolation of training effects"}, {"id": "da629a0d-8fc8-4943-b32f-5829d7b08b8f", "type": "concept", "title": "Intangible benefits"}], "description": "The point is to understand value, costs, benefits, and credible evidence."}, {"id": "507649d9-512f-456d-aafa-156b503697b0", "type": "subtopic", "title": "Evaluation planning", "children": [{"id": "9b7c2a73-f2cb-4eff-95ee-05646b1b723f", "type": "concept", "title": "Evaluation questions"}, {"id": "7b26c515-22d5-4642-89ca-777477950dcc", "type": "concept", "title": "Baseline and follow-up data"}, {"id": "f4b58a9d-7af9-4f50-9a6b-6c0393ee2c5c", "type": "concept", "title": "Data sources and timing"}], "description": "Students learn to build evaluation into the design from the beginning."}, {"id": "651865a5-3c95-4271-b6ad-00c13f170b1d", "type": "subtopic", "title": "Using evaluation findings", "children": [{"id": "8f5b180c-4f48-45f4-b9d4-133fa4aee645", "type": "concept", "title": "Reporting to stakeholders"}, {"id": "4520008b-e6f0-4131-b02f-0a079a506d61", "type": "concept", "title": "Iterating training design"}, {"id": "691df665-91aa-42d7-a5ed-2a2d74dce4b6", "type": "concept", "title": "Decision making about scale or sunset"}], "description": "This subtopic turns evaluation into improvement."}]}, {"id": "b0ba513f-2203-41be-bf46-81d8e78acd24", "type": "topic", "title": "Training Module Design", "description": "The training module is the applied capstone of the course. Students learn to create a coherent module with objectives, content, activities, assessments, facilitator guidance, and evaluation plans.", "children": [{"id": "2861d4a5-7f42-4f66-a2dc-a75d9fb3a679", "type": "subtopic", "title": "Module blueprint", "children": [{"id": "226a5677-393d-409e-9a5f-96363c37be53", "type": "concept", "title": "Audience and need statement"}, {"id": "084ab13b-d306-4eea-a6bf-b3c0527be3b8", "type": "concept", "title": "Objectives and timing"}, {"id": "99d77f50-c890-497c-ad8a-797da89e2d21", "type": "concept", "title": "Content, activity, assessment, and transfer plan"}], "description": "Students learn to organize a module before building slides or media."}, {"id": "a3454a50-3de7-480d-8677-bf894259a4ac", "type": "subtopic", "title": "Materials development", "children": [{"id": "adba8d09-c2c7-456b-98b7-bdf0d0eac744", "type": "concept", "title": "Facilitator guide"}, {"id": "ca4ad354-2b6e-4eb4-aa08-cab45a33ac24", "type": "concept", "title": "Participant handouts"}, {"id": "c6d0d640-7b06-4cc2-a54d-fa5a809f0bec", "type": "concept", "title": "Slides, scenarios, and job aids"}], "description": "The gist is to create learner-centered materials that support practice."}, {"id": "4828099a-7045-45c0-a207-75344c437320", "type": "subtopic", "title": "Practice and assessment design", "children": [{"id": "4dcb8e39-6082-480b-a59a-3b7180dc4329", "type": "concept", "title": "Scenario practice"}, {"id": "e995f137-e709-4756-a6f8-6e772ad07464", "type": "concept", "title": "Skill demonstration"}, {"id": "1b8428bf-9af9-4218-a202-5b1c26ab5819", "type": "concept", "title": "Rubrics and answer keys"}], "description": "Students learn to verify learning through doing."}, {"id": "f8f3a16e-a751-46d2-9898-d8abddbdff47", "type": "subtopic", "title": "Pilot and revision", "children": [{"id": "124fd3a9-8093-484c-9eca-1288131292a1", "type": "concept", "title": "Usability review"}, {"id": "7f5efa8d-ea1d-40b4-85c7-f5890e3ae14e", "type": "concept", "title": "Learner feedback"}, {"id": "d0a7a5d5-49de-4740-b0af-b5fb73a05b2c", "type": "concept", "title": "Revision based on evidence"}], "description": "This subtopic helps students test before launch."}]}, {"id": "034578ec-b0f1-419b-9a37-b7152c83bab6", "type": "topic", "title": "Learning Transfer and Performance Consulting", "description": "This added topic makes transfer and performance improvement explicit. Students learn that training is only one intervention and that the real goal is improved workplace performance.", "children": [{"id": "ad1637b0-aab5-4ab4-8139-345303110142", "type": "subtopic", "title": "Performance consulting mindset", "children": [{"id": "c024f0bb-fcab-4f06-8abe-2377901053a7", "type": "concept", "title": "Performance gaps and root causes"}, {"id": "edeefa89-fc22-4b16-ba7c-737ee6188b19", "type": "concept", "title": "Environmental barriers"}, {"id": "d0a0b495-a597-4583-8f42-768f3a7573a0", "type": "concept", "title": "Non-training solutions"}], "description": "Students learn to diagnose the broader performance system before prescribing training."}, {"id": "0c8e4842-c9b7-401d-bf5a-9379c56491a5", "type": "subtopic", "title": "Transfer design", "children": [{"id": "c2430e02-d9e3-42ee-b9a7-66ed5db80581", "type": "concept", "title": "Pre-training manager alignment"}, {"id": "17e6b066-a597-4c19-aa43-d01caf073487", "type": "concept", "title": "Post-training practice and reinforcement"}, {"id": "3fce84fd-8b91-42ab-8e3e-fb38e71a57c6", "type": "concept", "title": "Job aids and workflow integration"}], "description": "The point is to make learning stick after the session ends."}, {"id": "e094d06d-3379-4224-b58b-087bcb97b9ca", "type": "subtopic", "title": "Manager and peer support", "children": [{"id": "253475a9-f967-44b8-ac29-e8bada211fd7", "type": "concept", "title": "Coaching conversations"}, {"id": "aefbd792-50cc-4be2-8a8b-017bae86cfc1", "type": "concept", "title": "Peer learning groups"}, {"id": "e60d627d-4217-481e-9972-d88b66e434a9", "type": "concept", "title": "Accountability routines"}], "description": "Students learn how social context drives behavior change."}, {"id": "69b6ac98-65d5-40a1-bd16-430fa552163e", "type": "subtopic", "title": "Measuring transfer", "children": [{"id": "4b8e175d-f01b-47ad-a9e0-80ac16687439", "type": "concept", "title": "On-the-job observation"}, {"id": "18f3c525-ed78-44c9-879a-6daa1d50d4b8", "type": "concept", "title": "Behavior indicators"}, {"id": "2947cb25-4c18-498e-a2c5-7280ced3a95a", "type": "concept", "title": "Follow-up surveys and performance data"}], "description": "This subtopic tracks whether learning becomes behavior."}]}, {"id": "1bca4baa-c5da-4a22-996a-8b61da7dad26", "type": "topic", "title": "Skills-Based Talent Development, AI, and Learning Analytics", "description": "This added topic brings the course into current L&D practice. Students learn how organizations use skills data, AI-enabled tools, and learning analytics to plan development, personalize learning, and support mobility.", "children": [{"id": "a1ab3584-c1f7-4708-a430-e0d5ca59e588", "type": "subtopic", "title": "Skills-based development", "children": [{"id": "033a6fa7-80dd-4b56-9f9d-0d676a6607eb", "type": "concept", "title": "Skills taxonomies"}, {"id": "aeb04810-187a-47de-9475-75eb448da086", "type": "concept", "title": "Capability academies"}, {"id": "8f755c35-fa7d-4d49-aa7b-48215c67d675", "type": "concept", "title": "Career pathways and internal mobility"}], "description": "Students learn to design development around capabilities rather than only jobs or courses."}, {"id": "442ca8d4-9f9d-4301-bc79-7e760c499056", "type": "subtopic", "title": "AI-enabled learning tools", "children": [{"id": "5f041012-4092-4260-bbcd-2eaf2a2aa393", "type": "concept", "title": "Personalized learning recommendations"}, {"id": "c2923b7b-4ffc-4f24-a766-bd9df08f24ea", "type": "concept", "title": "Content generation and curation"}, {"id": "d58f08f6-0ec7-480e-bfee-d6bfbb51af5d", "type": "concept", "title": "Chatbots, simulations, and practice feedback"}], "description": "The gist is to evaluate how AI can support learning while managing risk."}, {"id": "1c936034-fe87-4c98-b0c4-31df332f839f", "type": "subtopic", "title": "Learning analytics", "children": [{"id": "5e139463-be38-4d30-b03c-e170c2c6ccdd", "type": "concept", "title": "Participation, completion, assessment, and engagement data"}, {"id": "cc24da6f-ce11-43a0-87ef-3553b7c49524", "type": "concept", "title": "Skill growth and proficiency tracking"}, {"id": "bf63bf1d-c117-4f42-a2fc-376b807de872", "type": "concept", "title": "Dashboards and action planning"}], "description": "Students learn to interpret learning data for decisions."}, {"id": "ddfff45d-06a0-4faa-aa78-c25c3daae440", "type": "subtopic", "title": "Ethics, privacy, and bias", "children": [{"id": "a024ffd9-86b8-4053-9492-9db4a03458c1", "type": "concept", "title": "Employee data privacy"}, {"id": "91ba4b60-0535-4c35-a21e-d00fb2610ed2", "type": "concept", "title": "Algorithmic bias"}, {"id": "8e35073a-9c0c-4749-9f3b-49e8a12990de", "type": "concept", "title": "Transparency and human oversight"}], "description": "This subtopic keeps learning technology responsible."}]}], "dbBacked": true}$trdvjson$::jsonb,
